app.post('/tarefas', (req, res) => {
  const { titulo } = req.body;
  if (!titulo) return res.status(400).json({ erro: 'titulo é obrigatório' });  // valida
  const nova = criar(titulo);
  res.status(201).json(nova);   // 201: criado
});
app.get('/tarefas/:id', (req, res) => {
  const t = achar(req.params.id);
  if (!t) return res.status(404).json({ erro: 'não existe' });
  res.json(t);                  // 200 implícito
});

// POST cria sempre um novo -> NÃO idempotente (repetir duplica)
app.post('/tarefas', (req, res) => { res.status(201).json(criar(req.body.titulo)); });

// PUT define o estado do recurso -> idempotente (repetir converge)
app.put('/tarefas/:id', (req, res) => {
  const t = substituir(req.params.id, req.body);   // mesmo corpo = mesmo resultado
  if (!t) return res.status(404).end();
  res.json(t);
});
